typedef float rational_t;

extern "C" float sqrtf(float);

class Random {
public:
  unsigned int NextRand();
  int rand(int end) {
    unsigned int r = NextRand();
    return r % end;
  }
  float randf(float begin, float end) {
    unsigned int r = NextRand();
    return r * (1.0f/32767)*(end-begin) + begin;
  }
};

extern Random *g_random_ptr;

inline int random(int end) {
  int i = g_random_ptr->rand(end);
  return i;
}

inline float random(float begin, float end) {
  float r = g_random_ptr->randf(begin, end);
  return r;
}

#define PLUS_MINUS_ONE (random(-1.0f, 1.0f))

class vector3d {
public:
  rational_t x;
  rational_t y;
  rational_t z;

  vector3d() {}
  vector3d(rational_t _x, rational_t _y, rational_t _z)
    : x(_x), y(_y), z(_z) {}

  rational_t length2() const {
    return x*x + y*y + z*z;
  }

  void normalize() {
    rational_t l2 = length2();
    if (l2 > 1.0e-10f) {
      rational_t one_over_l = 1.0f / sqrtf(l2);
      x *= one_over_l;
      y *= one_over_l;
      z *= one_over_l;
    }
  }
};

inline vector3d operator*(const vector3d& v, rational_t s) {
  return vector3d(v.x*s, v.y*s, v.z*s);
}

class physical_interface {
  char base[8];
  unsigned int flags;
  rational_t mass;
  rational_t volume;
  vector3d velocity;
  vector3d angular_velocity;
public:
  void set_angular_velocity(const vector3d& v) {
    angular_velocity = v;
  }
};

class guidance_system {
protected:
  physical_interface *owner;
  int flags;
public:
  virtual ~guidance_system();
};

class rocket_guidance_sys : public guidance_system {
protected:
  vector3d target_pos;
  void *target;
  rational_t launch_force;
  rational_t wobble_timer;
  rational_t guidance_delay;
  rational_t accel_delay;
  rational_t guided_accuracy;
  rational_t turn_factor;
  rational_t accel_factor;
  rational_t full_wobble_timer;
  rational_t full_guidance_delay;
  rational_t full_accel_delay;
  rational_t wobble_timer_var;
  rational_t guidance_delay_var;
  rational_t accel_delay_var;

  void wobble();

public:
  rational_t get_turn_factor() const {
    return turn_factor;
  }

  rational_t get_wobble_timer_with_var() const {
    return full_wobble_timer + (PLUS_MINUS_ONE*wobble_timer_var);
  }
};

void rocket_guidance_sys::wobble()
{
  vector3d axis = vector3d(PLUS_MINUS_ONE, PLUS_MINUS_ONE, PLUS_MINUS_ONE);
  axis.normalize();

  owner->set_angular_velocity(axis * (3.14159265358979323846f * get_turn_factor()) * ((random(2)) ? 1 : -1));
  wobble_timer = get_wobble_timer_with_var();
}
